out=[row[:] for row in grid]
# fill between consecutive marker cells in each row and column
for r in range(7):
    cs=[c for c,v in enumerate(grid[r]) if v==2]
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b): out[r][c]=3
for c in range(24):
    rs=[r for r in range(7) if grid[r][c]==2]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b): out[r][c]=3
print('\n'.join(' '.join(map(str,r)) for r in out))
